#!/bin/sh
# Makes build.nbt from scratch: build.mjs to a temp file, then the roof preset check once the shell exists, then mv.
set -eu
cd "$(dirname "$0")"
MCD=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs
tmp=build.tmp.nbt
trap 'rm -f "$tmp"' EXIT

node build.mjs "$tmp"

# The roofs are built in node by roofSpec (parts/roofs.mjs), so this preset step is a dry-run report only (it writes
# nothing); running it for real would put a second roof over the first.
if grep -q '^// STUB' parts/main-shell.mjs; then
  echo "roof step skipped: the shell is still a stub"
else
  node "$MCD" roof "$tmp" --preset cottage --style hip --material dark-slate --dry-run
fi

mv "$tmp" build.nbt
echo "wrote build.nbt"
// room: Bedroom 3 (guest room). Inner air x31..34, y6..8, z12..16 (plan.md ROOMS). Entered from the east passage through
// the door at (33,6..7,17); window (32..33,6..8,11) on the north wall, left clear.
// Layout: the bed lies against the west partition (head at x31, foot at x32, z14) with a nightstand either side of the
// head; the dresser stands on the east wall (x34, z12..13) under the window's east side; the x33 column is the walkway
// from the door to the window. A hanging lantern over the foot of the bed is the ceiling light.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const FLOOR_Y = 6;

export function build(g) {
  // bed: foot at (32,6,14) and head at (31,6,14), both facing west (foot to head)
  g.set(32, FLOOR_Y, 14, "white_bed", { facing: "west", part: "foot" });
  g.set(31, FLOOR_Y, 14, "white_bed", { facing: "west", part: "head" });

  // nightstands either side of the head, each with a lantern on top
  g.set(31, FLOOR_Y, 13, "dark_oak_planks");
  g.set(31, FLOOR_Y, 15, "dark_oak_planks");
  g.set(31, FLOOR_Y + 1, 13, ...B.lantern(false));
  g.set(31, FLOOR_Y + 1, 15, "flower_pot");

  // dresser on the east wall: two blocks, a flower pot and a lantern on top
  g.set(34, FLOOR_Y, 12, "dark_oak_planks");
  g.set(34, FLOOR_Y, 13, "dark_oak_planks");
  g.set(34, FLOOR_Y + 1, 12, "flower_pot");
  g.set(34, FLOOR_Y + 1, 13, ...B.lantern(false));

  // ceiling light over the bed foot, hung from the top plate at y9
  g.set(33, 8, 14, ...B.lantern(true));
}
